// @vitest-environment node
import{it,expect,vi}from'vitest';import{prepareStoppedRuntimeBundle,applyStoppedRuntimeEdges}from'./stoppedRuntimeBundle.js';import{inspectStoppedRuntime}from'./stoppedRuntimeSnapshot.js';import{contextPreparationBlocksIdle as blocked,requestContextIdle as idle}from'./contextPreparationRegistry.js';import{setPerfChoice}from'../audio/perfMode';import{fakeGenerator,fakeClock,deferred}from'./stoppedRuntime.fixture.js';
function setup(){const{g,context}=fakeGenerator(),environment={context,checkRuntime:vi.fn(),roleWanderFactory:()=>{}},envRelease=vi.fn(async()=>{}),clock=fakeClock(context),clockRelease=vi.fn(async()=>{}),bundle={dispose:vi.fn(async()=>{}),check:vi.fn(),describe:()=>({})},options={prepareEnvironment:vi.fn(async()=>({context,value:environment,release:envRelease})),sourceClock:vi.fn(async()=>({context,value:clock,release:clockRelease})),buildOwners:vi.fn(async()=>bundle)};return{g,context,environment,envRelease,clock,clockRelease,bundle,options};}
function binding(f,p){const old=f.g.roles.lead.instrument,from=f.context.createGain(),oldTo=f.context.createGain(),next=f.context.createGain();from.connect(oldTo);return{version:1,context:f.context,from,oldTo,next,preflight:vi.fn(),edges:()=>({remove:[[from,oldTo]],add:[[from,next]]}),publish:vi.fn(()=>{f.g.roles.lead.instrument={preset:{new:true}};f.g.audioEnvironment=f.environment;return'installed';}),restore:vi.fn(()=>{f.g.roles.lead.instrument=old;delete f.g.audioEnvironment;}),retirePrevious:vi.fn(async()=>{}),old};}
it('claims the preparation hold and explicit Native wake before any awaited environment work',async()=>{const f=setup();f.context.state='suspended';const p=prepareStoppedRuntimeBundle(f.g,f.options);expect(blocked(f.context)).toBe(true);expect(f.context.resume).toHaveBeenCalledOnce();await p.ready;expect(f.options.prepareEnvironment).toHaveBeenCalledOnce();expect(f.g.roles.lead.instrument.preset.id).toBe('lead');await p.cancel();expect(f.bundle.dispose).toHaveBeenCalledOnce();expect(f.clockRelease).toHaveBeenCalledOnce();expect(f.envRelease).toHaveBeenCalledOnce();});
it('retains the hold through a cancelled late environment lease and its explicit release ACK',async()=>{const f=setup(),late=deferred(),ack=deferred();f.options.prepareEnvironment.mockReturnValue(late.promise);const p=prepareStoppedRuntimeBundle(f.g,f.options);p.ready.catch(()=>{});await vi.waitFor(()=>expect(f.options.prepareEnvironment).toHaveBeenCalledOnce());let closed=false;const cancelled=p.cancel().then(()=>closed=true);late.resolve({context:f.context,value:f.environment,release:()=>ack.promise});await Promise.resolve();await idle(f.context,()=>true);expect(f.context.suspend).not.toHaveBeenCalled();expect(closed).toBe(false);ack.resolve();await cancelled;expect(f.options.sourceClock).not.toHaveBeenCalled();expect(f.options.buildOwners).not.toHaveBeenCalled();expect(blocked(f.context)).toBe(false);});
it('refuses cached cold source authority and releases explicit leases without calling a global clock disposer',async()=>{const f=setup(),dispose=vi.fn();f.clock.snapshot=()=>({...fakeClock(f.context).snapshot(),creationState:'suspended',spec:{rate:48000,epochFrame:0}});f.clock.dispose=dispose;const p=prepareStoppedRuntimeBundle(f.g,f.options);await expect(p.ready).rejects.toThrow(/running future/);expect(f.options.buildOwners).not.toHaveBeenCalled();expect(f.clockRelease).toHaveBeenCalledOnce();expect(dispose).not.toHaveBeenCalled();});
it('a settings edit after candidate preparation refuses commit and retires the candidate before old-owner mutation',async()=>{const f=setup(),p=prepareStoppedRuntimeBundle(f.g,f.options);await p.ready;const b=binding(f,p);f.g.settings.drums.kit='crisp';await expect(p.commit(b)).rejects.toThrow(/changed/);expect(b.publish).not.toHaveBeenCalled();expect(b.retirePrevious).not.toHaveBeenCalled();expect(f.bundle.dispose).toHaveBeenCalledOnce();expect(f.g.roles.lead.instrument).toBe(b.old);});
it('publishes synchronously while retaining previous-owner idle hold through ACK and preserving G/transport/listeners',async()=>{const f=setup(),transport=f.g.transport,listeners=f.g.planListeners,p=prepareStoppedRuntimeBundle(f.g,f.options);await p.ready;const b=binding(f,p),ack=deferred();b.retirePrevious.mockReturnValue(ack.promise);const owner=await p.commit(b);expect(owner.value).toBe('installed');expect(f.g.transport).toBe(transport);expect(f.g.planListeners).toBe(listeners);expect(blocked(f.context)).toBe(true);await idle(f.context,()=>true);expect(f.context.suspend).not.toHaveBeenCalled();ack.resolve();await owner.previousRetirement;expect(blocked(f.context)).toBe(false);expect(b.from.edges.has(b.next)).toBe(true);await owner.scope.retire();expect(f.bundle.dispose).toHaveBeenCalledOnce();});
it('restores exact old edges when a new connect throws, then cleans every candidate lease',async()=>{const f=setup(),p=prepareStoppedRuntimeBundle(f.g,f.options);await p.ready;const b=binding(f,p);b.from.connect.mockImplementation(to=>{if(to===b.next)throw Error('new edge failed');b.from.edges.add(to);});await expect(p.commit(b)).rejects.toThrow('new edge failed');expect(b.from.edges.has(b.oldTo)).toBe(true);expect(b.from.edges.has(b.next)).toBe(false);expect(f.g.roles.lead.instrument).toBe(b.old);expect(b.publish).not.toHaveBeenCalled();expect(b.retirePrevious).not.toHaveBeenCalled();expect(f.bundle.dispose).toHaveBeenCalledOnce();expect(blocked(f.context)).toBe(false);});
it('restores target-owned pointer changes as well as Native edges after publication fails',async()=>{const f=setup(),p=prepareStoppedRuntimeBundle(f.g,f.options);await p.ready;const b=binding(f,p);b.publish.mockImplementation(()=>{f.g.roles.lead.instrument={preset:{bad:true}};throw Error('pointer publish failed');});await expect(p.commit(b)).rejects.toThrow('pointer publish failed');expect(b.restore).toHaveBeenCalledOnce();expect(f.g.roles.lead.instrument).toBe(b.old);expect(b.from.edges.has(b.oldTo)).toBe(true);expect(b.from.edges.has(b.next)).toBe(false);expect(b.retirePrevious).not.toHaveBeenCalled();});
it('retains a visible reservation quarantine if exact rollback itself cannot complete',async()=>{const f=setup(),p=prepareStoppedRuntimeBundle(f.g,f.options);await p.ready;const b=binding(f,p);b.from.connect.mockImplementation(()=>{throw Error('Native inverse failed');});await expect(p.commit(b)).rejects.toThrow(/rollback/);expect(p.describe()).toMatchObject({state:'failed',rollbackQuarantined:true,reservation:{state:'cleanup-failed'}});expect(blocked(f.context)).toBe(true);expect(f.bundle.dispose).toHaveBeenCalledOnce();expect(b.retirePrevious).not.toHaveBeenCalled();});
it('requires explicit synchronous Generator-owned commit/restore and leaves invalid bindings uninstalled',async()=>{const f=setup(),p=prepareStoppedRuntimeBundle(f.g,f.options);await p.ready;const b=binding(f,p);b.publish=async()=>{};await expect(p.commit(b)).rejects.toThrow(/Generator-owned/);expect(b.preflight).not.toHaveBeenCalled();expect(f.bundle.dispose).not.toHaveBeenCalled();await p.cancel();});
it('validates every same-context edge before performing the first Native operation',()=>{const{context}=fakeGenerator(),from=context.createGain(),to=context.createGain(),foreign=fakeGenerator().context.createGain();from.connect(to);expect(()=>applyStoppedRuntimeEdges(context,{remove:[[from,to]],add:[[from,foreign]]})).toThrow(/same-context/);expect(from.edges.has(to)).toBe(true);expect(from.disconnect).not.toHaveBeenCalled();});it('refuses unsupported physical constructor before wake, environment or candidate allocation',()=>{const f=setup();f.g.roles.lead.instrument.preset={stringModel:'piano'};f.context.state='suspended';expect(()=>prepareStoppedRuntimeBundle(f.g,f.options)).toThrow(/partial-construction/);expect(f.context.resume).not.toHaveBeenCalled();expect(f.options.prepareEnvironment).not.toHaveBeenCalled();expect(f.options.buildOwners).not.toHaveBeenCalled();expect(blocked(f.context)).toBe(false);});it('does not release idle when a cancelled constructor later reports failed partial cleanup before returning an owner',async()=>{const f=setup(),late=deferred(),cleanup=Error('partial worker release failed');f.options.buildOwners.mockReturnValue(late.promise);const p=prepareStoppedRuntimeBundle(f.g,f.options);p.ready.catch(()=>{});await vi.waitFor(()=>expect(f.options.buildOwners).toHaveBeenCalledOnce());let closed=false;const cancelling=p.cancel().then(()=>closed=true);cancelling.catch(()=>{});await idle(f.context,()=>true);expect(f.context.suspend).not.toHaveBeenCalled();const primary=Error('constructor failed');primary.cleanupError=cleanup;late.reject(primary);await expect(p.ready).rejects.toBe(primary);await expect(cancelling).rejects.toThrow(/cleanup failed/);expect(closed).toBe(false);expect(blocked(f.context)).toBe(true);expect(p.describe()).toMatchObject({partialCleanupQuarantined:true,reservation:{state:'cleanup-failed'}});expect(p.describe().reservation.cleanupErrors.some(x=>x.error.includes('partial worker release failed'))).toBe(true);expect(f.envRelease).toHaveBeenCalledOnce();expect(f.clockRelease).toHaveBeenCalledOnce();});
it('cancellation before the child callback starts cannot deadlock the explicit pending guard',async()=>{const f=setup(),controller=new AbortController();f.options.buildOwners.mockImplementation(()=>{throw Error('must not construct');});f.options.sourceClock.mockImplementation(async()=>{controller.abort();return{context:f.context,value:f.clock,release:f.clockRelease};});const p=prepareStoppedRuntimeBundle(f.g,{...f.options,signal:controller.signal});await expect(p.ready).rejects.toBeTruthy();expect(f.options.buildOwners).not.toHaveBeenCalled();expect(blocked(f.context)).toBe(false);});
it('refuses an enabled optional FM-bank policy before Native wake or environment/owner construction',()=>{const f=setup();f.context.state='suspended';setPerfChoice(true);try{expect(()=>prepareStoppedRuntimeBundle(f.g,f.options)).toThrow(/Optional FM bank/);expect(f.context.resume).not.toHaveBeenCalled();expect(f.options.prepareEnvironment).not.toHaveBeenCalled();expect(f.options.buildOwners).not.toHaveBeenCalled();expect(blocked(f.context)).toBe(false);}finally{setPerfChoice(null);}});

it('retains exact failing edge index/operation/semantic label and reverses only prior successful edges',()=>{const{context}=fakeGenerator(),a=context.createGain(),b=context.createGain(),c=context.createGain(),d=context.createGain();a.connect(b);let failure;try{applyStoppedRuntimeEdges(context,{remove:[[a,b],[c,d]],removeLabels:['known source route','unknown return edge']});}catch(error){failure=error;}expect(failure.runtimeEdge).toMatchObject({operation:'disconnect',index:1,label:'unknown return edge',phase:'install'});expect(a.edges.has(b)).toBe(true);expect(c.connect).not.toHaveBeenCalled();});
